import type { MenuContextType, MenuProps, MenuType } from "./menu.types";

import React, { forwardRef, useEffect, useState, useMemo } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import * as RadixDropdownMenu from "@radix-ui/react-dropdown-menu";
import * as RadixContextMenu from "@radix-ui/react-context-menu";

import {
  MenuTrigger,
  MenuContent,
  MenuGroup,
  MenuLabel,
  MenuItem,
  MenuItemLabel,
  MenuItemSubtext,
  MenuItemHotkey,
  MenuItemLeadingIcon,
  MenuItemTrailingIcon,
  MenuCheckboxItem,
  MenuDivider,
  MenuSub,
  MenuSubTrigger,
  MenuSubContent,
} from "./subcomponents";
import { MenuClasses, StyledMenu, StyledMenuContent } from "./menu.styles";
import { MenuContext } from "./hooks/use-menu";
import { getMenuChildren } from "./utils/get-menu-children";

const getRadix = (type?: MenuType) => (type === "context" ? RadixContextMenu : RadixDropdownMenu);

const MenuRoot = forwardRef(
  (
    {
      variant = "default",
      children,
      className,
      defaultOpen = false,
      open,
      onOpenChange,
      modal = false,
      dismissible = true,
      containerElement,
      loop = true,
      side = "bottom",
      sideOffset = 4,
      align = "start",
      alignOffset = 0,
      onSelect,
      size = "default",
      type = "dropdown",
      ...props
    }: MenuProps,
    ref: React.ForwardedRef<HTMLDivElement>,
  ) => {
    const theme = useTheme();
    const rootClasses = clsx(MenuClasses.root, className);
    const [portalContainer, setPortalContainer] = useState<HTMLElement | Element | null>(null);

    useEffect(() => {
      const el = document.body.querySelector(`[data-textura-theme-provider="true"]`);
      setPortalContainer(containerElement || el || document.body);
    }, [containerElement]);

    const { trigger, content } = getMenuChildren(children);

    const radixRootProps = {
      open,
      defaultOpen,
      onOpenChange,
      modal,
    };

    const RadixComponent = useMemo(() => getRadix(type), [type]);

    const contextValue: MenuContextType = {
      dismissible,
      loop,
      side: side === "start" ? "left" : side === "end" ? "right" : side,
      sideOffset,
      align,
      alignOffset,
      onSelect,
      size,
      variant,
      RadixComponent,
    };

    return (
      <MenuContext.Provider value={contextValue}>
        <RadixComponent.Root {...radixRootProps}>
          <StyledMenu
            ref={ref}
            className={rootClasses}
            currentTheme={theme}
            variant={variant}
            {...props}
          >
            {trigger}
            <RadixComponent.Portal container={portalContainer}>
              <StyledMenuContent
                currentTheme={theme}
                styleSlots={props.styleSlots}
                variant={variant}
              >
                {content}
              </StyledMenuContent>
            </RadixComponent.Portal>
          </StyledMenu>
        </RadixComponent.Root>
      </MenuContext.Provider>
    );
  },
);
MenuRoot.displayName = "Menu";

const Menu = Object.assign(MenuRoot, {
  Trigger: MenuTrigger,
  Content: MenuContent,
  Group: MenuGroup,
  Label: MenuLabel,
  Item: MenuItem,
  ItemLabel: MenuItemLabel,
  ItemSubtext: MenuItemSubtext,
  ItemHotkey: MenuItemHotkey,
  ItemLeadingIcon: MenuItemLeadingIcon,
  ItemTrailingIcon: MenuItemTrailingIcon,
  CheckboxItem: MenuCheckboxItem,
  Divider: MenuDivider,
  Sub: MenuSub,
  SubTrigger: MenuSubTrigger,
  SubContent: MenuSubContent,
});

export default Menu;
